1	/**
2	 * Enrich the Shared Web Hosting plan tiers (HostingPlan rows) with the fields added
3	 * for the production-readiness push: bundled email `mailboxes`, `freeMigration`,
4	 * `featured`, and a `tagline`.
5	 *
6	 * UPDATE-IN-PLACE by design: for a plan that already exists (prod's Starter /
7	 * Business / Pro), the upsert's `update` sets ONLY the new fields — the name,
8	 * price, and resource limits are left exactly as they are. The `create` block only
9	 * fires in a fresh environment (e.g. a clean staging DB) and carries the canonical
10	 * tier definition so the storefront isn't empty there.
11	 *
12	 * Idempotent. Safe to re-run.
13	 * Run: cd /opt/nxeon && npx tsx prisma/seed-hosting-plans.ts
14	 */
15	import { PrismaClient } from "@prisma/client";
16	
17	const db = new PrismaClient();
18	
19	const PHP = "8.1,8.2,8.3";
20	
21	// slug → the NEW fields to set in place, plus canonical create-defaults (matching
22	// the live prod tiers) used only when the plan doesn't exist yet.
23	type Spec = {
24	  slug: string;
25	  newFields: { mailboxes: number; freeMigration: boolean; featured: boolean; tagline: string };
26	  create: { name: string; priceCents: number; diskGB: number; maxSites: number; maxDatabases: number; bandwidthTB: number; sortOrder: number };
27	};
28	
29	const SPECS: Spec[] = [
30	  {
31	    slug: "starter",
32	    newFields: { mailboxes: 1, freeMigration: false, featured: false, tagline: "Perfect for getting your first website online." },
33	    create: { name: "Starter", priceCents: 299, diskGB: 10, maxSites: 1, maxDatabases: 2, bandwidthTB: 1, sortOrder: 0 },
34	  },
35	  {
36	    slug: "business",
37	    newFields: { mailboxes: 10, freeMigration: true, featured: true, tagline: "For growing businesses running several sites." },
38	    create: { name: "Business", priceCents: 499, diskGB: 25, maxSites: 10, maxDatabases: 25, bandwidthTB: 2, sortOrder: 1 },
39	  },
40	  {
41	    slug: "pro",
42	    newFields: { mailboxes: 25, freeMigration: true, featured: false, tagline: "Maximum resources for high-traffic sites." },
43	    create: { name: "Pro", priceCents: 899, diskGB: 50, maxSites: 50, maxDatabases: 100, bandwidthTB: 4, sortOrder: 2 },
44	  },
45	];
46	
47	async function main() {
48	  let updated = 0;
49	  let created = 0;
50	  for (const s of SPECS) {
51	    const existing = await db.hostingPlan.findUnique({ where: { slug: s.slug }, select: { name: true, priceCents: true } });
52	    await db.hostingPlan.upsert({
53	      where: { slug: s.slug },
54	      update: { ...s.newFields }, // in place: ONLY the new fields
55	      create: { slug: s.slug, ...s.create, ...s.newFields, phpVersions: PHP, active: true },
56	    });
57	    if (existing) {
58	      updated++;
59	      console.log(`  updated  ${existing.name.padEnd(10)} ($${(existing.priceCents / 100).toFixed(2)} kept) → ${s.newFields.mailboxes} mailbox(es)${s.newFields.freeMigration ? " · free migration" : ""}${s.newFields.featured ? " · ★" : ""}`);
60	    } else {
61	      created++;
62	      console.log(`  created  ${s.create.name.padEnd(10)} ($${(s.create.priceCents / 100).toFixed(2)}) → ${s.newFields.mailboxes} mailbox(es)${s.newFields.freeMigration ? " · free migration" : ""}${s.newFields.featured ? " · ★" : ""}`);
63	    }
64	  }
65	  const total = await db.hostingPlan.count();
66	  console.log(`\nHostingPlans: ${updated} updated in place, ${created} created. Total in DB: ${total}.`);
67	}
68	
69	main()
70	  .catch((e) => {
71	    console.error(e);
72	    process.exit(1);
73	  })
74	  .finally(async () => {
75	    await db.$disconnect();
76	  });
