1	/**
2	 * Seed the Business Email mailbox-hosting tiers (EmailPlan rows).
3	 *
4	 * Three sensible tiers priced per month:
5	 *   - Starter  : 1 mailbox  / 10 GB each
6	 *   - Business : 5 mailboxes / 25 GB each
7	 *   - Pro      : 25 mailboxes / 50 GB each
8	 *
9	 * Idempotent: dedupes by `name` and upserts. Safe to re-run.
10	 *
11	 * Run: cd /opt/nxeon && npx tsx prisma/seed-email-plans.ts
12	 */
13	import { PrismaClient } from "@prisma/client";
14	
15	const db = new PrismaClient();
16	
17	type TierSpec = {
18	  name: string;
19	  mailboxes: number;
20	  storageGB: number;
21	  priceCents: number;
22	  termMonths: number;
23	  sortOrder: number;
24	};
25	
26	const TIERS: TierSpec[] = [
27	  { name: "Starter", mailboxes: 1, storageGB: 10, priceCents: 199, termMonths: 1, sortOrder: 0 },
28	  { name: "Business", mailboxes: 5, storageGB: 25, priceCents: 799, termMonths: 1, sortOrder: 1 },
29	  { name: "Pro", mailboxes: 25, storageGB: 50, priceCents: 2499, termMonths: 1, sortOrder: 2 },
30	];
31	
32	async function main() {
33	  let created = 0;
34	  let updated = 0;
35	
36	  for (const spec of TIERS) {
37	    const data = {
38	      name: spec.name,
39	      mailboxes: spec.mailboxes,
40	      storageGB: spec.storageGB,
41	      priceCents: spec.priceCents,
42	      termMonths: spec.termMonths,
43	      active: true,
44	      sortOrder: spec.sortOrder,
45	    };
46	
47	    // No DB unique constraint on name — dedupe manually.
48	    const existing = await db.emailPlan.findFirst({ where: { name: spec.name } });
49	    if (existing) {
50	      await db.emailPlan.update({ where: { id: existing.id }, data });
51	      updated++;
52	    } else {
53	      await db.emailPlan.create({ data });
54	      created++;
55	    }
56	    console.log(
57	      `  ${spec.name.padEnd(10)} ${spec.mailboxes} mailbox(es) · ${spec.storageGB} GB each · ${(spec.priceCents / 100).toFixed(2)}/${spec.termMonths}mo`,
58	    );
59	  }
60	
61	  const total = await db.emailPlan.count();
62	  console.log(`\nEmailPlans seeded: ${created} created, ${updated} updated. Total in DB: ${total}.`);
63	}
64	
65	main()
66	  .catch((e) => {
67	    console.error(e);
68	    process.exit(1);
69	  })
70	  .finally(async () => {
71	    await db.$disconnect();
72	  });
