1	import Link from "next/link";
2	import type { Metadata } from "next";
3	import { db } from "@/lib/db";
4	import { Section, SectionTitle, PageHero } from "@/components/marketing/primitives";
5	import { FeatureCard, CtaBand } from "@/components/marketing/sections";
6	import { MailInbox } from "@/components/marketing/showcase/MailInbox";
7	import { Reveal } from "@/components/marketing/Reveal";
8	import {
9	  IconMail,
10	  IconGlobe,
11	  IconShield,
12	  IconClock,
13	  IconCheck,
14	  IconArrow,
15	} from "@/components/marketing/icons";
16	import { currentPromo, promoEndsAt, promoPriceCents } from "@/lib/promotions";
17	import { PromoBadge } from "@/components/marketing/PromoBadge";
18	import { PromoCountdown } from "@/components/marketing/PromoCountdown";
19	
20	// Prices come from the same db.emailPlan records the portal sells, so an admin
21	// edit can never desync this marketing page from checkout.
22	export const dynamic = "force-dynamic";
23	
24	export const metadata: Metadata = {
25	  title: "Business Email",
26	  description:
27	    "Professional email on your own domain — webmail, IMAP/SMTP, spam and virus filtering, and shared calendars. Rolling out now: reserve your plan and activate at launch.",
28	};
29	
30	const WHY = [
31	  {
32	    icon: <IconGlobe />,
33	    title: "Email on your own domain",
34	    body: "Send and receive as you@yourbrand.com instead of a generic address. Every message reinforces your brand, not someone else's.",
35	  },
36	  {
37	    icon: <IconMail />,
38	    title: "Webmail + IMAP/SMTP",
39	    body: "Use the built-in webmail from any browser, or connect Outlook, Apple Mail, Thunderbird, and your phone over standard IMAP and SMTP.",
40	  },
41	  {
42	    icon: <IconShield />,
43	    title: "Spam & virus filtering",
