53	type Tier = {
54	  name: string;
55	  // Regular price in cents = the real renewal price (shown struck through). The
56	  // discounted first-term price is derived with promoPriceCents at render time.
57	  priceCents: number;
58	  cadence: string;
59	  tagline: string;
60	  features: string[];
61	  popular?: boolean;
62	};
63	
64	// The db.emailPlan model carries name / mailboxes / storageGB / priceCents /
65	// termMonths but no marketing copy, so we derive the tagline and feature bullets
66	// here. Tagline falls back gracefully for admin-created tiers with novel names.
67	const TAGLINES: Record<string, string> = {
68	  Starter: "A professional inbox for you.",
69	  Business: "Email for a small team.",
70	  Pro: "Room for the whole company.",
71	};
72	
73	/** Format cents as a dollar string ("$1.99", "$25"). */
74	function money(cents: number): string {
75	  const v = cents / 100;
76	  return Number.isInteger(v) ? `$${v}` : `$${v.toFixed(2)}`;
77	}
78	
79	type EmailPlanRecord = {
80	  name: string;
81	  mailboxes: number;
82	  storageGB: number;
83	  priceCents: number;
84	  termMonths: number;
85	};
86	
87	/** Build the marketing tier view-model from a db.emailPlan record. */
88	function tierFromPlan(p: EmailPlanRecord, popular: boolean): Tier {
89	  return {
90	    name: p.name,
91	    priceCents: p.priceCents,
92	    cadence: p.termMonths > 1 ? `/${p.termMonths} mo` : "/mo",
93	    tagline: TAGLINES[p.name] ?? "Professional email on your own domain.",
94	    features: [
95	      `${p.mailboxes} mailbox${p.mailboxes === 1 ? "" : "es"}`,
96	      `${p.storageGB} GB per mailbox`,
97	      "Webmail + IMAP/SMTP",
98	      "Spam & virus filtering",
99	    ],
100	    popular,
101	  };
102	}
103	
104	const SETUP = [
105	  "Add your domain and we generate the exact records to publish",
106	  "Set the MX records so mail routes to your mailboxes",
107	  "Add the SPF record so your outgoing mail is properly identified",
108	];
109	
