125	  const popularIndex = plans.length > 1 ? Math.floor((plans.length - 1) / 2) : -1;
126	  const tiers: Tier[] = plans.map((p, i) => tierFromPlan(p, i === popularIndex));
127	
128	  return (
129	    <>
130	      <PageHero
131	        eyebrow="Business Email · Rolling out"
132	        title="Professional email on"
133	        highlight="your own domain"
134	        sub="Mailboxes at your brand's domain — webmail, IMAP/SMTP for any client, spam and virus filtering, and shared calendars. We're connecting our mail partner now; reserve your plan and your mailboxes activate the moment it goes live."
135	        primary={{ label: "Reserve your plan", href: "/register" }}
136	        secondary={{ label: "Get a domain", href: "/domains" }}
137	        visual={<MailInbox />}
138	      />
139	
140	      {/* Why business email */}
141	      <Section size="lg">
142	        <SectionTitle
143	          eyebrow="Why business email"
144	          title="Look the part in every inbox"
145	          sub="A free address works until the first client sees it. Business email gives your team credibility, control, and tools built for real work."
146	        />
147	        <div className="mt-12 grid gap-5 sm:grid-cols-2 lg:grid-cols-4">
148	          {WHY.map((f, i) => (
149	            <FeatureCard key={f.title} icon={f.icon} title={f.title} delay={(i % 4) * 60}>
150	              {f.body}
151	            </FeatureCard>
152	          ))}
153	        </div>
154	      </Section>
155	
156	      {/* Pricing */}
157	      <Section tone="panel" size="lg" id="pricing">
158	        <SectionTitle
159	          eyebrow="Pricing"
160	          title="Simple per-mailbox pricing"
161	          sub="Pay monthly, add mailboxes as your team grows, and manage everything from the same dashboard as your servers and domains."
162	        />
163	        {/* Honest promo banner: badge + real countdown + transparent renewal note. */}
164	        <div className="mx-auto mt-8 flex max-w-2xl flex-wrap items-center justify-center gap-x-3 gap-y-2 rounded-2xl border border-brand-500/25 bg-gradient-to-r from-accent-blue/10 to-brand-500/10 px-5 py-3 text-center">
165	          <PromoBadge promo={promo} />
