167	            <span className="font-semibold text-white">{promo.discountPercent}% off your first term</span>
168	            {" — renews at the regular price."}
169	          </span>
170	          <PromoCountdown
171	            endsAt={promoEndsIso}
172	            prefix={`${promo.name} ends in`}
173	            className="text-sm font-semibold grad-text"
174	          />
175	        </div>
176	        {tiers.length === 0 && (
177	          <p className="mx-auto mt-12 max-w-xl text-center text-sm text-slate-400">
178	            Plans are being finalised for launch.{" "}
179	            <Link href="/register" className="text-brand-300 hover:underline">
180	              Reserve your spot
181	            </Link>{" "}
182	            and we&apos;ll email you the moment mailboxes go live.
183	          </p>
184	        )}
185	        <div className="mt-12 grid gap-5 lg:grid-cols-3">
186	          {tiers.map((t, i) => (
187	            <Reveal
188	              key={t.name}
189	              delay={i * 80}
190	              className={`card lift relative flex h-full flex-col ${
191	                t.popular ? "border-brand-500/40 glow-brand" : ""
192	              }`}
193	            >
194	              {t.popular && (
195	                <span className="absolute -top-3 left-1/2 -translate-x-1/2 rounded-full border border-brand-500/30 bg-brand-500/15 px-3 py-1 text-[11px] font-semibold uppercase tracking-[0.12em] text-brand-200">
196	                  Most popular
